insert into categories (slug, name, numeral, note, intro) values ('wars', 'Wars', 'I', 'Conflicts that redrew maps', 'Prolonged conflicts between states and peoples — the great ruptures that ended empires and drew the borders we live with.');
insert into categories (slug, name, numeral, note, intro) values ('battles', 'Battles', 'II', 'Single days that decided eras', 'Compressed violence: one field, one day, one decision. Each of these engagements bent the longer war around it.');
insert into categories (slug, name, numeral, note, intro) values ('empires', 'Empires', 'III', 'Civilizations at their height', 'The large orders — how they rose, what held them together, and what their collapse left behind.');
insert into categories (slug, name, numeral, note, intro) values ('people', 'People', 'IV', 'Lives that bent history', 'Individuals whose choices scaled up: generals, rulers, and voices that carried further than their own lifetimes.');
insert into categories (slug, name, numeral, note, intro) values ('technology', 'Technology', 'V', 'Machines and material craft', 'Instruments of power and knowledge — from concrete that heals in seawater to machines that ended the battleship age.');
insert into categories (slug, name, numeral, note, intro) values ('oddities', 'Oddities', 'VI', 'Strange but documented events', 'The archive''s cabinet of curiosities: mysteries, impossible missions, and events that read like fiction but happened.');
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('001', 'battle-of-midway', 'Battle of Midway', 'The turning point of the Pacific War', 'battles', NULL, '1942-06-04', '1942-06-07', 'Midway Atoll', 'Pacific Ocean', 28.2, -177.38, TRUE, 'Four days in June 1942 when American codebreakers and dive-bombers sank four Japanese carriers.', 'Six months after Pearl Harbor, Japan was unbeatable on paper. An undefeated fleet, a perimeter from Burma to the Gilberts, and Admiral Yamamoto''s plan to finish the US Pacific Fleet with a decisive battle at Midway Atoll. What Yamamoto did not know was that Commander Joseph Rochefort''s codebreakers at Station HYPO had cracked enough of the Japanese naval code to read the plan itself, target, date, and order of battle.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('002', 'd-day', 'D-Day', 'The Allied invasion of Normandy', 'battles', NULL, '1944-06-06', NULL, 'Normandy, France', 'France', 49.41, -0.87, TRUE, 'The Allied invasion of Normandy, 156,000 men across five beaches in a single day.', 'By 1944 Germany occupied Europe from Norway to Greece, and Stalin had spent two years demanding a second front. The answer was Operation Overlord. Nearly 7,000 naval vessels, 11,590 aircraft, and some 156,000 men assembled in southern England for an assault on five Normandy beaches codenamed Utah, Omaha, Gold, Juno, and Sword.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('003', 'christmas-truce', 'The Christmas Truce', 'An unofficial ceasefire in the trenches', 'oddities', NULL, '1914-12-25', NULL, 'Western Front', NULL, 50.85, 2.89, TRUE, 'On Christmas Day 1914, enemy soldiers climbed out of their trenches, exchanged gifts, and played football.', 'By December 1914 the Western Front had frozen into trenches from the sea to Switzerland, and both high commands expected a short war to resume in spring. In the line, the reality was mud, corpses between the trenches, and the first Christmas away from home for millions of young men who had marched off in August to cheering crowds.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('004', 'siege-of-constantinople', 'The Siege of Constantinople', 'The fall of an empire', 'wars', NULL, '1453-04-06', '1453-05-29', 'Constantinople', 'Byzantine Empire', 41.01, 28.98, TRUE, 'Fifty-three days in 1453 when Ottoman cannon ended a thousand years of Byzantine empire.', 'By 1453 the Byzantine Empire was a city-state with suburbs. Constantinople itself, the despotate of Morea in Greece, and a few Aegean islands, all that remained of eleven centuries of Roman rule in the east. Sultan Mehmed II, twenty-one years old and in the second year of his reign, resolved to take the city his predecessors had besieged and failed to take for six hundred years.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('005', 'napoleon-bonaparte', 'Napoleon Bonaparte', '1769–1821', 'people', NULL, '1769-08-15', '1821-05-05', 'Ajaccio, Corsica', 'France', 48.85, 2.35, TRUE, 'The Corsican artillery officer who crowned himself emperor and then lost everything in Russia and at Waterloo.', 'Napoleon Bonaparte was born in Ajaccio, Corsica, in 1769, one year after France bought the island from Genoa, and trained as an artillery officer in the royal army. The Revolution made his career. At Toulon in 1793 his guns drove the British from the harbour, and by 1796, aged twenty-six, he commanded the French army in Italy, winning a string of victories that made him a national hero.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('006', 'roman-concrete-mystery', 'The Roman Concrete Mystery', 'Why ancient harbours still stand', 'technology', NULL, '0300-01-01', NULL, 'Rome', 'Roman Empire', 41.9, 12.5, TRUE, 'Volcanic ash, lime, and seawater, a concrete that heals itself while modern concrete crumbles.', 'Modern concrete fails in decades, especially in seawater. Salt infiltrates, steel rebar rusts and expands, and piers crumble within a human lifetime. Roman harbours, breakwaters, and domes have stood for two thousand years, some growing stronger in the surf. The secret, lost with the empire, was pozzolana. Volcanic ash from the Bay of Naples mixed with slaked lime.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('007', 'world-war-i', 'World War I', 'The war that ended empires', 'wars', NULL, '1914-07-28', '1918-11-11', 'Europe and beyond', 'Global', 43.86, 18.41, TRUE, 'The industrial war that toppled four empires at a cost of more than fifteen million dead.', 'On 28 June 1914 a Bosnian Serb student shot Archduke Franz Ferdinand of Austria-Hungary in Sarajevo. Five weeks later, a cascade of alliances, mobilization timetables, and ultimatums had dragged every great power in Europe into war. Germany''s Schlieffen Plan, a vast wheeling attack through Belgium meant to knock France out in six weeks, failed at the Marne in September, and both sides dug trenches from the Swiss border to the English Channel.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('008', 'world-war-ii', 'World War II', 'The largest conflict in history', 'wars', NULL, '1939-09-01', '1945-09-02', 'Europe, Pacific, Africa', 'Global', 52.23, 21.01, TRUE, 'A global war of more than sixty million dead that ended with a divided world.', 'On 1 September 1939 Germany invaded Poland, and within days Britain and France declared war. What began as a European conflict spread across six continents. U-boat wolf packs in the Atlantic, desert armies in North Africa, island-hopping campaigns across the Pacific, and, above all, the colossal land war between Germany and the Soviet Union in the east.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('009', 'vietnam-war', 'Vietnam War', 'The war the superpower lost', 'wars', NULL, '1955-11-01', '1975-04-30', 'Vietnam', 'Vietnam', 21.03, 105.85, TRUE, 'America''s longest losing war, guerrillas, helicopters, and a credibility gap that scarred a superpower.', 'Vietnam was two wars at once. A civil war between communist North Vietnam and the US-backed South, and a Cold War test of whether American power could stop communism in Asia. It began with advisers under Eisenhower and Kennedy, Americanized under Johnson after the disputed Gulf of Tonkin incident in 1964, and peaked at 543,000 US troops in 1968.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('010', 'american-civil-war', 'American Civil War', 'A nation torn in two', 'wars', NULL, '1861-04-12', '1865-04-09', 'United States', 'United States', 38.9, -77.04, TRUE, 'Four years that killed some 620,000 soldiers, ended slavery, and decided what America was.', 'The war began over slavery''s future and ended by settling it. When Lincoln won the presidency in 1860 on a platform of stopping slavery''s expansion, eleven Southern states seceded rather than accept even that limit, forming a Confederacy whose vice president declared slavery its cornerstone. Confederate guns opened on Fort Sumter on 12 April 1861.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('011', 'napoleonic-wars', 'Napoleonic Wars', 'Twelve years that made modern Europe', 'wars', NULL, '1803-05-18', '1815-06-18', 'Europe', 'France', 48.85, 2.35, TRUE, 'Twelve years of France against shifting coalitions, the wars that invented modern Europe.', 'The Napoleonic Wars were really one war with intermissions. From the breakdown of the Treaty of Amiens in May 1803 to Waterloo in June 1815, France fought seven coalitions in shifting combinations of Britain, Austria, Prussia, Russia, Spain, and Portugal. At stake was whether revolutionary France''s empire would replace Europe''s old order.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('012', 'waterloo', 'Battle of Waterloo', 'Napoleon''s last gamble', 'battles', NULL, '1815-06-18', NULL, 'Waterloo', 'Belgium', 50.71, 4.41, TRUE, '72,000 French against Wellington''s 68,000, decided when 30,000 Prussians marched out of the woods.', 'Napoleon escaped Elba in March 1815 and reclaimed France without firing a shot. The powers that had just finished carving up Europe at Vienna immediately declared him an outlaw and assembled their armies. Napoleon, with some 300,000 men raised but only about 72,000 immediately available, chose to strike first, smashing into Belgium to destroy Wellington''s Anglo-allied army and Blücher''s Prussians separately before the Austrians and Russians could arrive.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('013', 'stalingrad', 'Battle of Stalingrad', 'The deadliest battle ever fought', 'battles', NULL, '1942-08-23', '1943-02-02', 'Stalingrad', 'Soviet Union', 48.71, 44.52, TRUE, 'Five months of street fighting that swallowed a German army and broke the Wehrmacht for good.', 'In the summer of 1942 Hitler split his southern offensive to seize both the Caucasus oilfields and the city bearing Stalin''s name. The Sixth Army under Friedrich Paulus reached the Volga at Stalingrad in August and the Luftwaffe reduced the city to rubble within days, rubble that proved ideal for defence. General Vasily Chuikov, given command of the Soviet 62nd Army, ordered his men to hug the Germans. Stay so close that German artillery and aircraft could not fire without hitting their own.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('014', 'thermopylae', 'Battle of Thermopylae', 'Three hundred against an empire', 'battles', NULL, '-0480-08-01', NULL, 'Thermopylae', 'Greece', 38.8, 22.54, TRUE, 'Three hundred Spartans and their allies held a mountain pass against Persia for three days in 480 BC.', 'In 480 BC Xerxes I of Persia marched to finish what his father Darius had started at Marathon. The conquest of Greece. His army, ancient sources claim millions, modern estimates still run to six figures, crossed the Hellespont on bridges of boats and came south along the coast. The Greeks chose to meet it at Thermopylae, the Hot Gates. A pass so narrow that numbers meant nothing and the long Persian spears broke against the longer Greek ones.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('015', 'gettysburg', 'Battle of Gettysburg', 'The high-water mark of the Confederacy', 'battles', NULL, '1863-07-01', '1863-07-03', 'Gettysburg, Pennsylvania', 'United States', 39.83, -77.23, TRUE, 'Three days in Pennsylvania that broke the Confederacy''s last invasion of the North.', 'In June 1863 Robert E. Lee marched 71,000 Confederates into Pennsylvania, seeking supplies, foreign recognition, and a victory on Northern soil that might break the Union''s will before the 1864 elections. The armies collided by accident at Gettysburg on 1 July, where Union cavalry under Buford held the ridges long enough for infantry to occupy the fishhook line of Cemetery Ridge.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('016', 'pearl-harbor', 'Attack on Pearl Harbor', 'A date which will live in infamy', 'battles', NULL, '1941-12-07', NULL, 'Pearl Harbor, Hawaii', 'United States', 21.36, -157.94, TRUE, 'Japan''s carrier strike that sank a battle line, missed the carriers, and woke an industrial giant.', 'By late 1941 Japan faced a choice American oil and steel embargoes had forced on it. Abandon the war in China or seize Southeast Asia''s resources and accept war with the United States. Admiral Yamamoto, who had studied at Harvard and knew exactly what American industry could do, gambled that a single crippling blow would buy Japan six months of free conquest and a negotiated peace.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('017', 'hastings', 'Battle of Hastings', 'The day England changed hands', 'battles', NULL, '1066-10-14', NULL, 'Hastings', 'England', 50.86, 0.57, TRUE, 'One October day in 1066 when Norman cavalry broke an English shield wall and changed a language forever.', 'The year 1066 had three kings of England. When Edward the Confessor died childless in January, the crown went to Harold Godwinson, but William, Duke of Normandy, claimed Edward had promised it to him, and Harald Hardrada of Norway claimed it through older treaties. In September Hardrada landed in the north. Harold marched 240 miles in four days, destroyed the Vikings at Stamford Bridge on 25 September, killing Hardrada, then turned around and force-marched south when William landed at Pevensey on the 28th.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('018', 'julius-caesar', 'Julius Caesar', '100–44 BC', 'people', NULL, '-0100-07-12', '-0044-03-15', 'Rome', 'Roman Republic', 41.9, 12.5, TRUE, 'The general who conquered Gaul, crossed the Rubicon against the Senate, and was stabbed twenty-three times for it.', 'Gaius Julius Caesar was born in July 100 BC into an ancient but cash-poor patrician family, and spent his youth dodging the dictator Sulla, who had him proscribed as a teenager. He bought his way upward the Roman way. Borrowed fortunes, spectacular games for the people, priesthoods, and a talent for spotting which way the political wind blew. In 60 BC he stitched together the First Triumvirate with Pompey and Crassus, Rome''s richest general and its greatest soldier, and used the consulship of 59 BC to push through land laws by open intimidation.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('019', 'genghis-khan', 'Genghis Khan', '1162–1227', 'people', NULL, '1162-01-01', '1227-08-18', 'Mongolian steppe', 'Mongol Empire', 47.92, 106.92, TRUE, 'The orphaned outcast who united the steppe and conquered more land than any commander in history.', 'He was born Temüjin around 1162, son of a minor chief who was poisoned by rivals, leaving the boy''s family abandoned on the steppe to survive, by legend, on roots and marmots. What followed is one of history''s great reversals. Through alliances, betrayals survived, and a ruthlessness that became policy, Temüjin united the Mongol tribes and in 1206 had himself proclaimed Genghis Khan, universal ruler, on the Onon river.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('020', 'winston-churchill', 'Winston Churchill', '1874–1965', 'people', NULL, '1874-11-30', '1965-01-24', 'Blenheim Palace, England', 'United Kingdom', 51.5, -0.13, TRUE, 'The voice that held Britain together in 1940, soldier, writer, and twice prime minister.', 'Winston Churchill was born in 1874 into Britain''s highest aristocracy and spent his first fifty years collecting careers. Cavalry officer in Cuba, India, and Sudan. War correspondent escaped from a Boer prison. MP by twenty-six. The minister who created the modern dreadnought navy. The scapegoat of Gallipoli in 1915, who resigned, served in the trenches, and clawed his way back to Chancellor of the Exchequer by 1924.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('021', 'george-washington', 'George Washington', '1732–1799', 'people', NULL, '1732-02-22', '1799-12-14', 'Virginia', 'United States', 38.71, -77.09, TRUE, 'The general who lost most of his battles, won the war, then walked away from power, twice.', 'George Washington was a Virginia planter and veteran of Britain''s French and Indian War, where he learned, at Braddock''s defeat in 1755, how regular armies die in American woods. When Congress needed a commander in June 1775, he was the obvious and only choice. A southerner to bind the South to what was then a New England rebellion, a man of visible dignity, and one rich enough to serve unpaid.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('022', 'cleopatra', 'Cleopatra VII', '69–30 BC', 'people', NULL, '-0069-01-01', '-0030-08-10', 'Alexandria', 'Ptolemaic Egypt', 31.2, 29.92, TRUE, 'The last pharaoh, a scholar-queen who wagered Egypt on Caesar and Antony, and lost it to Octavian.', 'Cleopatra VII was born in 69 BC into the Ptolemaic dynasty, Macedonian Greeks who had ruled Egypt for two and a half centuries without bothering to learn Egyptian. She was the exception. Educated in philosophy, mathematics, and debate, fluent in perhaps seven languages, and reportedly the first of her line to speak Egyptian. She took the throne at eighteen alongside her ten-year-old brother-husband Ptolemy XIII, in a kingdom bankrupt, fractious, and living on Roman sufferance.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('023', 'roman-empire', 'Roman Empire', '27 BC – 1453 AD', 'empires', NULL, '-0027-01-16', '1453-05-29', 'Rome', 'Mediterranean world', 41.9, 12.5, TRUE, 'Fifteen centuries of Rome, from Augustus to the fall of Constantinople, the template of Western empire.', 'On 16 January 27 BC the Senate granted Octavian the name Augustus, and the Roman Republic, hollowed out by a century of civil war, became a monarchy that called itself a republic. What followed was the longest political success story in Western history. Two centuries of relative internal peace, the Pax Romana, during which some fifty million people around an entire sea lived under one law, used one currency over half the territory, and travelled roads that remained the best in Europe for a thousand years.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('024', 'ottoman-empire', 'Ottoman Empire', '1299–1922', 'empires', NULL, '1299-01-01', '1922-11-01', 'Constantinople', 'Middle East and Balkans', 41.01, 28.98, TRUE, 'Six centuries of sultans, from Anatolian beylik to a three-continent empire dissolved by world war.', 'Around 1299 a chieftain named Osman led a small band of Turkish warriors on the Byzantine frontier. His descendants turned that beylik into a state-building machine. Peasant infantry (the Janissaries, recruited through the devshirme levy of Christian boys), meritocratic administration, and a dynasty so durable it survived 36 sultans without a single successful usurpation from outside the family.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('025', 'mongol-empire', 'Mongol Empire', '1206–1368', 'empires', NULL, '1206-01-01', '1368-01-01', 'Karakorum', 'Eurasian steppe', 47.21, 102.85, TRUE, 'From Genghis''s death to Kublai''s China, the empire that ruled half of Eurasia and connected it.', 'Genghis Khan died in 1227 with his empire stretching from the Pacific to the Caspian and his succession unsettled. What followed astonished even the Mongols. Instead of fragmenting, the empire kept conquering. Ögedei, elected Great Khan in 1229, finished the Jin dynasty of northern China. His generals Subutai and Batu then turned west, shattering Rus'' principalities, Poland, and Hungary between 1236 and 1242, stopping, famously, only when Ögedei''s death recalled the princes to elect a successor.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('026', 'byzantine-empire', 'Byzantine Empire', '330–1453', 'empires', NULL, '0330-05-11', '1453-05-29', 'Constantinople', 'Eastern Mediterranean', 41.01, 28.98, TRUE, 'Rome''s eastern half, eleven centuries of emperors, schisms, sieges, and survival against every odd.', 'When Constantine dedicated Constantinople on 11 May 330, he meant it as a new Rome. Within a century and a half it was the only Rome that mattered. While the western provinces dissolved into Germanic kingdoms, the eastern empire, Greek-speaking, Christian, fabulously wealthy from Anatolian taxes and Silk Road tolls, carried Roman law, administration, and the imperial title forward for another thousand years.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('027', 'ancient-egypt', 'Ancient Egypt', '3100–30 BC', 'empires', NULL, '-3100-01-01', '-0030-08-10', 'Nile Valley', 'Egypt', 29.98, 31.13, TRUE, 'Three thousand years of pharaohs, the longest continuous civilization in human history.', 'Egypt''s civilization grew from the Nile''s annual flood, which laid fresh silt across a desert valley and made farming so reliable that priests, scribes, and kings could live off the surplus. Around 3100 BC, traditionally under a king remembered as Narmer or Menes, Upper and Lower Egypt were united into a single kingdom, and the machinery of divine kingship clicked into place for the next three millennia.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('028', 'tanks', 'The Tank', 'Landships, 1916 to today', 'technology', NULL, '1916-09-15', NULL, 'The Somme, France', 'United Kingdom', 50.05, 2.73, TRUE, 'The armoured box that broke the trench deadlock, and still anchors every army a century later.', 'The tank was born of the Western Front''s arithmetic. Machine guns made infantry attack suicide, artillery made defence impregnable, and barbed wire made the ground between them impassable. Britain''s Landships Committee answered with an armoured box on caterpillar tracks that could crush wire, cross trenches, and carry machine guns into the enemy line. Secrecy gave it the cover name, factory workers were told they were building water tanks.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('029', 'battleships', 'Battleships', 'Queens of the sea, 1906–1945', 'technology', NULL, '1906-02-10', '1945-09-02', 'Global oceans', 'Global', 50.8, -1.09, TRUE, 'Floating fortresses that ruled the seas for forty years, then died in an afternoon of air power.', 'On 10 February 1906 HMS Dreadnought slid down the ways and made every battleship on earth obsolete overnight. Uniform 12-inch guns, steam-turbine speed, and armour thick enough to matter. Every navy had to start over, and the Anglo-German dreadnought race, expensive, public, and politically toxic, helped poison Europe''s last peacetime decade.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('030', 'submarines', 'Submarines', 'The weapon that starves nations', 'technology', NULL, '1914-09-22', NULL, 'North Sea', 'Germany', 54.32, 10.14, TRUE, 'From U-boat terror to the invisible deterrent hiding under the ice, the weapon that starves nations.', 'The submarine began as a coastal toy and became, twice, Germany''s best hope of strangling Britain. On 22 September 1914 a single U-boat, U-9, sank three British cruisers in an hour, proof that a £100,000 boat could kill a £1,000,000 ship. By 1917 unrestricted submarine warfare was sinking British shipping faster than shipyards could replace it. Only the belated convoy system, which forced U-boats to face escorted merchants instead of lone victims, saved Britain, and the U-boat campaign''s excesses helped bring America into the war.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('031', 'printing-press', 'Printing Press', 'Gutenberg''s machine, c. 1440', 'technology', NULL, '1440-01-01', NULL, 'Mainz', 'Holy Roman Empire', 50, 8.27, TRUE, 'Movable type that cut book costs a hundredfold, and made ideas uncontrollable.', 'Around 1440 in Mainz, the goldsmith Johannes Gutenberg combined three existing things, the wine press, oil-based ink, and metal type that could be set, printed, melted, and reset, into a machine that changed what knowledge was. A scribe needed months for one Bible. Gutenberg''s workshop printed some 180 copies of his great Latin Bible around 1455, each as beautiful as manuscript and a fraction of the eventual cost.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('032', 'doolittle-raid', 'The Doolittle Raid', 'Eighty men, sixteen bombers', 'oddities', NULL, '1942-04-18', NULL, 'Tokyo, Japan', 'Japan', 35.68, 139.69, TRUE, 'Sixteen bombers off an aircraft carrier, the impossible raid that answered Pearl Harbor.', 'Four months after Pearl Harbor, America had nothing to show but defeats. The Philippines falling, the fleet rebuilding, the public desperate for retaliation. Lieutenant Colonel Jimmy Doolittle, racing pilot, aeronautical engineer, already famous, proposed the unthinkable. Fly Army medium bombers off a Navy carrier, bomb Japan, and keep flying to China. Every expert said bombers could neither take off from a carrier deck nor land back on one. Doolittle''s answer was to do neither. Take off, and don''t come back.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('033', 'tunguska-event', 'Tunguska Event', 'The explosion with no crater', 'oddities', NULL, '1908-06-30', NULL, 'Siberia', 'Russian Empire', 60.92, 101.96, TRUE, 'In 1908 something exploded over Siberia with hundreds of Hiroshimas'' force, and left no crater.', 'Around 7:17 on the morning of 30 June 1908, witnesses across hundreds of kilometres of Siberia saw the sky split. A fireball brighter than the sun, a column of fire, then shockwaves that knocked men off porches 60 kilometres away, shattered windows, and registered on barometers as far as London. At the Podkamennaya Tunguska river, some 80 million trees lay flattened radially across more than 2,000 square kilometres, trunks pointing away from an empty centre.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('034', 'roanoke-lost-colony', 'Roanoke, the Lost Colony', '115 people, one carved word', 'oddities', NULL, '1590-08-18', NULL, 'Roanoke Island', 'North America', 35.88, -75.67, TRUE, '115 colonists, one carved word, CROATOAN, and four centuries without an answer.', 'In 1587 Sir Walter Raleigh''s latest venture planted some 115 English men, women, and children on Roanoke Island, off what is now North Carolina. The colony was a private speculation. John White, gentleman-artist, as governor. His pregnant daughter and son-in-law among the settlers. Their child Virginia Dare, born that August, the first English baby born in the Americas.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('035', 'panama-canal', 'Panama Canal', 'The ditch that moved the world', 'oddities', NULL, '1914-08-15', NULL, 'Panama', 'Panama', 9.08, -79.68, TRUE, 'A French bankruptcy, some 25,000 dead of disease, then America''s locks joined two oceans.', 'Cutting Central America in half had been dreamed since Balboa. A ship sailing New York to San Francisco travelled 13,000 miles around Cape Horn, and the 1849 gold rush made the shortcut urgent. Ferdinand de Lesseps, fresh from Suez, promised a sea-level canal through Panama, and walked into a rainforest that defeated him. Between 1881 and 1889 his company lost some 22,000 workers, overwhelmingly to malaria and yellow fever, before collapsing in the century''s most spectacular bankruptcy.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('036', 'cold-war', 'Cold War', 'The half-century standoff', 'wars', NULL, '1947-03-12', '1991-12-26', 'Berlin, Germany', 'Global', 52.52, 13.4, TRUE, 'Two superpowers armed to the teeth who never fought directly, and divided the world for 44 years.', 'The Cold War began in the ruins of 1945, when the wartime alliance of the United States and the Soviet Union collapsed into mutual suspicion. America emerged with its industry intact, a monopoly on the atomic bomb, and bases ringing Eurasia. The Soviet Union held Eastern Europe with some eleven million soldiers and a conviction, hardened by twenty million dead, that it would never again be invaded from the west. The Truman Doctrine of March 1947, aid to any government resisting communism, drew the line openly.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('037', 'french-revolution', 'French Revolution', 'Liberty, terror, and the guillotine', 'wars', NULL, '1789-05-05', '1799-11-09', 'Paris, France', 'France', 48.85, 2.35, TRUE, 'A bankrupt monarchy called the Estates-General, and unleashed a decade that ate its own children.', 'France in 1789 was the richest state in Europe and functionally bankrupt. Wars in America, a regressive tax system that exempted nobles and clergy, and bread prices that ate half a labourer''s wage. Louis XVI''s summoning of the Estates-General, unmet since 1614, was meant to raise money. The Third Estate instead declared itself the National Assembly and swore, in a tennis court, not to disband until a constitution existed.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('038', 'black-death', 'Black Death', 'The plague that remade a continent', 'oddities', NULL, '1347-10-01', '1353-12-31', 'Messina, Sicily', 'Europe', 38.19, 15.55, TRUE, 'A bacillus that sailed from the Black Sea and killed a third of Europe in six years.', 'In October 1347 twelve Genoese galleys limped into Messina, most of their crews dead or dying of a sickness of swellings in groin and armpit, black blotches, and a cough that brought blood. Within weeks the contagion was ashore. It moved the way trade moved. Ship to port, port to market town, market to village, reaching Paris by mid-1348, London by autumn, Scandinavia and Russia by 1350.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('039', 'industrial-revolution', 'Industrial Revolution', 'Coal, iron, and the factory', 'technology', NULL, '1760-01-01', '1840-01-01', 'Manchester, England', 'United Kingdom', 53.48, -2.24, TRUE, 'How Britain''s mills and mines made the modern economy, and the modern city.', 'Around 1760 Britain burned wood and worked iron in forges little changed since Rome. Eighty years later it burned coal, smelted iron with coke, spun cotton in factories, and moved goods on iron rails behind steam locomotives. Output of pig iron rose roughly tenfold. Cotton cloth, once a luxury import, became Britain''s great export. The change was concentrated in the north, Manchester, Birmingham, Leeds, Glasgow, where coal lay near ports and workers.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('040', 'apollo-11', 'Moon Landing / Apollo 11', 'One small step from a Florida pad', 'technology', NULL, '1969-07-16', '1969-07-24', 'Kennedy Space Center, Florida', 'United States', 28.58, -80.65, TRUE, 'Four days, three men, one Sea of Tranquility, the only time humans walked on another world.', 'Apollo 11 lifted off on 16 July 1969 behind 7.5 million pounds of Saturn V thrust, carrying Neil Armstrong, Buzz Aldrin, and Michael Collins toward a rendezvous computed on slide rules. Three days later Columbia slipped behind the Moon, and the lunar module Eagle, with Armstrong and Aldrin aboard, dropped toward the Sea of Tranquility while Collins kept station alone overhead.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('041', 'cuban-missile-crisis', 'Cuban Missile Crisis', 'Thirteen days on the nuclear brink', 'wars', NULL, '1962-10-16', '1962-10-28', 'Havana, Cuba', 'Cuba', 23.11, -82.36, TRUE, 'Soviet missiles 90 miles from Florida, thirteen days when Washington and Moscow stared down annihilation.', 'In the summer of 1962 Nikita Khrushchev secretly shipped nuclear missiles, bombers, and some 40,000 troops to Cuba, Fidel Castro''s allied island 145 kilometres from Florida. The motives mixed. Defend Cuba after the Bay of Pigs fiasco, redress a missile gap that favoured America roughly seventeen to one, and force a Berlin settlement. American U-2 photographs on 14 October caught the launch sites rising at San Cristóbal, and on the morning of 16 October the prints reached President Kennedy.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('042', 'fall-of-berlin-wall', 'Fall of the Berlin Wall', 'The night the East walked west', 'oddities', NULL, '1989-11-09', NULL, 'Berlin, Germany', 'Germany', 52.52, 13.4, TRUE, 'A bungled press conference, then thousands with hammers on a wall that had divided a city for 28 years.', 'The Berlin Wall went up in August 1961 to stop East Germany bleeding its young through Berlin''s open sector border, some 3.5 million had already left. For 28 years it worked as designed. 155 kilometres of concrete, wire, dogs, and orders to shoot, dividing streets, cemeteries, and families. By autumn 1989 it guarded a state that no longer believed in itself.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('043', 'russian-revolution', 'Russian Revolution', 'Two revolutions in eight months', 'wars', NULL, '1917-03-08', '1917-11-07', 'Petrograd, Russia', 'Russia', 59.93, 30.33, TRUE, 'Bread queues in February, Bolshevik guards in October, the Tsar falls and Lenin seizes the vacant state.', 'Russia entered 1917 losing a war it could not feed. Some 1.7 million soldiers dead, railways broken, cities starving while grain rotted in the countryside. On 8 March, International Women''s Day, textile workers struck in Petrograd and soldiers ordered to fire instead fraternized. Within days the Tsar''s ministers fled, Nicholas II abdicated on 15 March, and a Provisional Government of liberals and moderate socialists inherited a collapsing army and an unanswered question. Land for peasants, peace for soldiers.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('044', 'american-revolution', 'American Revolution', 'Taxed, armed, and independent', 'wars', NULL, '1775-04-19', '1783-09-03', 'Lexington, Massachusetts', 'United States', 42.44, -71.22, TRUE, 'Thirteen colonies that refused a tax, built an army, and left an empire with French help.', 'The quarrel began over who paid for the Seven Years'' War. Britain, debt doubled, taxed its American colonies through the Sugar Act, the Stamp Act, and the Townshend duties, and met boycotts, mobs, and the argument, sharpened by pamphlets, that taxation without representation was tyranny. The Boston Tea Party of December 1773 answered the Tea Act with 342 chests in the harbour. Parliament answered with the Coercive Acts closing Boston''s port and garrisoning the town.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('045', 'chernobyl-disaster', 'Chernobyl Disaster', 'A test that burned through the roof', 'oddities', NULL, '1986-04-26', NULL, 'Pripyat, Ukraine', 'Ukraine', 51.38, 30.1, TRUE, 'A safety test at 1:23 a.m. Blew Reactor 4 apart, and exposed a superpower''s machinery of secrecy.', 'Chernobyl''s Reactor 4 was an RBMK, a Soviet design that used graphite to moderate the reaction and water to cool it, with the dangerous quirk that losing coolant could speed the reaction up. On 26 April 1986 operators ran a delayed safety test. With the reactor unstable at low power and safety systems disabled for the experiment, a power surge vaporized fuel channels in milliseconds. Two explosions lifted the 1,000-tonne lid and threw graphite and fuel across the roof.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('046', 'titanic', 'Titanic', 'The unsinkable ship''s first voyage', 'oddities', NULL, '1912-04-10', '1912-04-15', 'North Atlantic Ocean', 'Atlantic Ocean', 41.73, -49.94, TRUE, 'The largest liner afloat struck an iceberg on its maiden voyage, 1,500 dead for lack of boats.', 'RMS Titanic left Southampton on 10 April 1912 as the pride of the White Star Line. 269 metres, 46,000 tons, sixteen watertight compartments, and a press corps calling her practically unsinkable. Aboard were some 2,224 people, emigrants in steerage, millionaires in first class, and a crew that had never drilled a full evacuation.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('047', 'alexander-the-great', 'Alexander the Great', '356–323 BC, king of Macedon', 'people', NULL, '-0356-07-20', '-0323-06-10', 'Pella, Macedon', 'Macedonia', 40.76, 22.52, TRUE, 'A twenty-year-old king who conquered from Greece to India in twelve years, and died at thirty-two.', 'Alexander inherited Macedon in 336 BC at twenty, after his father Philip, who had forged Greece into a federation under Macedonian arms, was assassinated at a wedding. Within two years Alexander crossed to Asia with some 40,000 men, announcing a war of revenge against Persia. At Granicus, Issus, and Gaugamela he destroyed the armies of Darius III, took Tyre by causeway after a seven-month siege, and was crowned pharaoh in Egypt, where he founded Alexandria.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('048', 'joan-of-arc', 'Joan of Arc', '1412–1431, the Maid of Orléans', 'people', NULL, '1412-01-06', '1431-05-30', 'Orléans, France', 'France', 47.9, 1.9, TRUE, 'A peasant girl who heard voices, lifted a siege, crowned a king, and burned at nineteen.', 'Joan was born around 1412 in Domrémy, a border village in a France losing the Hundred Years'' War. Henry V had taken Normandy, allied Burgundy, and left the dauphin Charles discredited and uncrowned. At thirteen, Joan later testified, saints began speaking, Michael, Catherine, Margaret, urging her to support Charles and expel the English. In 1429, aged seventeen, she convinced the governor of Vaucouleurs to escort her through enemy country to Chinon.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('049', 'alan-turing', 'Alan Turing', '1912–1954, codebreaker and computer pioneer', 'people', NULL, '1912-06-23', '1954-06-07', 'Bletchley Park, England', 'United Kingdom', 51.99, -0.74, TRUE, 'The mathematician who broke Naval Enigma, imagined the computer, then was destroyed by his own country.', 'Alan Turing published On Computable Numbers in 1936, aged 24, defining an abstract universal machine, tape, symbols, states, that could simulate any other machine''s logic. The paper answered a question in mathematical logic. It also sketched the stored-program computer a decade before one existed. By 1939 the Government Code and Cypher School recruited him to Bletchley Park, where Britain attacked Germany''s Enigma cipher.
insert into entries (id, slug, title, subtitle, category_slug, subcategory, start_date, end_date, location, country, latitude, longitude, approximate, short_description, overview, historical_context, causes, key_events, consequences, lesser_known_facts, legacy, historical_significance, hero_image, tags) values ('050', 'haitian-revolution', 'Haitian Revolution', 'The only successful slave revolution', 'wars', NULL, '1791-08-22', '1804-01-01', 'Cap-Français, Saint-Domingue', 'Haiti', 19.76, -72.2, TRUE, 'Enslaved Africans rose, beat three empires, and founded the second free republic in the Americas.', 'Saint-Domingue in 1789 was France''s richest colony and its cruelest. 500,000 enslaved Africans worked sugar plantations at mortality rates that required tens of thousands of new captives yearly. The French Revolution''s Declaration of the Rights of Man detonated inside that order. Free people of color demanded citizenship, poor whites rioted to keep it from them, and on the night of 22 August 1791 thousands of enslaved workers rose across the northern plain, burning plantations toward Cap-Français.
insert into people (name, role, description) values ('Chester Nimitz', 'US Pacific Fleet commander', 'Trusted the codebreakers over caution and risked his only carriers on their word.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Isoroku Yamamoto', 'Japanese fleet commander', 'Designed the perfect trap for a fleet that was not where his intelligence said it was.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Joseph Rochefort', 'Codebreaker, Station HYPO', 'Led the team whose JN-25 breaks, and whose water-plant ruse, made the ambush possible.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Dwight D. Eisenhower', 'Supreme Allied Commander', 'Held the quarrelling Allied coalition together and took the final go/no-go decision on the weather.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Erwin Rommel', 'German defender of Normandy', 'Built the Atlantic Wall obstacles and insisted the invasion be defeated on the beaches, then lost the argument over the Panzer reserves.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Bernard Montgomery', 'Allied ground commander', 'Planned the landing phase and commanded all ground forces ashore on 6 June.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Alfred Anderson', 'Black Watch private, witness', 'Played no football, he held a lookout post, but remembered the silence. Died in 2005, the last known participant.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Mehmed II', 'Ottoman Sultan', 'Twenty-one at the siege. Combined medieval siegecraft with gunpowder artillery.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Constantine XI', 'Last Byzantine Emperor', 'Refused to abandon the city and died sword in hand.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Giovanni Giustiniani', 'Genoese commander', 'Led the land-wall defence until wounded. The defence collapsed after his evacuation.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Josephine de Beauharnais', 'First wife', 'His great love and political asset. Divorced in 1810 for lack of an heir, never replaced in his affections.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Talleyrand', 'Foreign minister', 'The serving, surviving diplomat who managed Napoleon''s treaties, and quietly negotiated with his enemies throughout.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Vitruvius', 'Architect and author', 'His De architectura preserved the recipe, though nobody could make it work for 1,500 years.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Admir Masic (MIT)', 'Modern researcher', 'Led the microscopy work that finally explained the Roman recipe.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Winston Churchill', 'First Lord of the Admiralty', 'Pushed the disastrous Gallipoli campaign, then redeemed himself as a front-line officer before returning to government.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Erich Ludendorff', 'German quartermaster-general', 'Effectively ran Germany''s war from 1916, gambled everything on the 1918 offensives, then demanded an armistice.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Vladimir Lenin', 'Bolshevik leader', 'Turned Russia''s military collapse into revolution, pulling Russia out of the war and into civil war.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Franklin D. Roosevelt', 'US President', 'Moved America from neutrality to arsenal of democracy, bankrolling the Allies through Lend-Lease before Pearl Harbor.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Joseph Stalin', 'Soviet leader', 'Directed the war effort that absorbed and then broke the bulk of German land power, at a Soviet death toll above twenty million.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Adolf Hitler', 'German dictator', 'Ordered the war and the Holocaust. His strategic blunders, above all invading Russia, doomed his own Reich.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Ho Chi Minh', 'North Vietnamese leader', 'Combined Leninism with nationalism into an unbeatable independence narrative.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Vo Nguyen Giap', 'North Vietnamese general', 'Beat the French at Dien Bien Phu and then outlasted the Americans.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Lyndon B. Johnson', 'US President', 'Americanized the war while insisting he sought no wider war, and destroyed his presidency doing it.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Abraham Lincoln', 'US President', 'Defined the war as a test of democracy, freed the enslaved by proclamation and amendment, and was murdered five days after victory.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Ulysses S. Grant', 'Union general-in-chief', 'Understood the arithmetic and pressed it relentlessly until the Confederacy had nothing left to spend.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Robert E. Lee', 'Confederate commander', 'Brilliant tactician trapped in an unwinnable strategy. His surrender''s dignity shaped reunion mythology.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('George Washington', 'Founding predecessor, symbolic', 'The revolution''s general invoked by both sides as the war tested what his republic meant.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Napoleon Bonaparte', 'Emperor of the French', 'Won every coalition war until the Spanish ulcer and Russian snow broke his arithmetic.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Horatio Nelson', 'British admiral', 'Made Britain invulnerable at sea at Trafalgar, and thereby made Napoleon unbeatable on land irrelevant to ultimate victory.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Duke of Wellington', 'British commander', 'Learned the trade in India and Spain, then closed the account at Waterloo.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
insert into people (name, role, description) values ('Gebhard von Blücher', 'Prussian commander', 'Seventy-two years old, bruised from Ligny, he marched his army through mud to Waterloo, the battle''s true author.') on conflict (name) do update set role = excluded.role, description = coalesce(excluded.description, people.description);
